public class Attractions extends ListActivity implements Constants {
    private static String[] FROM = {Constants.TITLE, Constants.IMG, Constants._ID};
    private static String ORDER_BY = Constants.TITLE;
    private String WHERE = "OstanID=";
    private ListItemAdapter adapterA;
    SQLiteDatabase db;
    private IranData events;
    String[] images;
    private ListItem li;
    private List<ListItem> liList;
    private Typeface mitra;

    @Override // android.app.Activity
    public void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        requestWindowFeature(7);
        setRequestedOrientation(1);
        setContentView(R.layout.attr);
        getWindow().setFeatureInt(7, R.layout.custom_title);
        TextView rightText = (TextView) findViewById(R.id.right_text);
        this.mitra = Typeface.createFromAsset(getAssets(), "fonts/BMITRA.TTF");
        rightText.setTypeface(this.mitra);
        rightText.setText(getIntent().getStringExtra("ostan"));
        this.liList = new ArrayList();
        this.events = new IranData(this);
        this.db = this.events.getReadableDatabase();
        Cursor cursor = getEvents();
        showEvents(cursor);
    }

    private Cursor getEvents() {
        this.WHERE = String.valueOf(this.WHERE) + getIntent().getIntExtra("ostanID", 0);
        Cursor cursor = this.db.query(Constants.TABLE_NAME, FROM, this.WHERE, null, null, null, ORDER_BY);
        startManagingCursor(cursor);
        int i = 0;
        this.images = new String[cursor.getCount()];
        while (cursor.moveToNext()) {
            this.images[i] = cursor.getString(1);
            i++;
        }
        return cursor;
    }

    private void showEvents(Cursor cursor) {
        cursor.moveToFirst();
        do {
            this.li = new ListItem();
            this.li.name = cursor.getString(0);
            this.liList.add(this.li);
        } while (cursor.moveToNext());
        this.adapterA = new ListItemAdapter(this, this.liList);
        setListAdapter(this.adapterA);
    }

    @Override // android.app.ListActivity
    protected void onListItemClick(ListView l, View v, int position, long id) {
        Log.i("Attractions", "list item selected.");
        Log.i("Attractions", Long.toString(id));
        startActivity(new Intent(this, (Class<?>) Information.class).putExtra("imgID", this.images[position]).putExtra("images", this.images));
    }

    @Override // android.app.ListActivity, android.app.Activity
    protected void onDestroy() {
        this.events.close();
        super.onDestroy();
    }
}

