public class Information extends Activity implements Constants, View.OnClickListener {
    private static final int MENU_ADD_FAV = 1;
    private static final int MENU_DELETE_FAV = 2;
    private static final int MENU_MAIN = 5;
    private String WHERE = "image=";
    SQLiteDatabase db;
    private IranData events;
    String[] images1;
    private String img;
    private Typeface lotus;
    private Typeface mitra;
    private String title;
    private static String[] FROM = {Constants._ID, Constants.DESC, Constants.OSTAN, Constants.TITLE, Constants.IMG, Constants.INGRED};
    private static String ORDER_BY = Constants._ID;

    @Override // android.app.Activity
    public void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        requestWindowFeature(7);
        setRequestedOrientation(1);
        setContentView(R.layout.info);
        getWindow().setFeatureInt(7, R.layout.custom_title);
        this.lotus = Typeface.createFromAsset(getAssets(), "fonts/LOTUSB.TTF");
        this.mitra = Typeface.createFromAsset(getAssets(), "fonts/BMITRA.TTF");
        TextView mavad = (TextView) findViewById(R.id.mavad);
        TextView tahie = (TextView) findViewById(R.id.tahie);
        mavad.setTypeface(this.mitra);
        tahie.setTypeface(this.mitra);
        this.images1 = new String[getIntent().getStringArrayExtra("images").length];
        this.images1 = getIntent().getStringArrayExtra("images");
        this.events = new IranData(this);
        this.db = this.events.getReadableDatabase();
        Cursor cursor = getEvents();
        showEvents(cursor);
    }

    private Cursor getEvents() {
        this.WHERE = String.valueOf(this.WHERE) + getIntent().getStringExtra("imgID");
        Cursor cursor = this.db.query(Constants.TABLE_NAME, FROM, this.WHERE, null, null, null, ORDER_BY);
        startManagingCursor(cursor);
        TextView desc = (TextView) findViewById(R.id.Desc);
        TextView ingred = (TextView) findViewById(R.id.Ingred);
        TextView ostan = (TextView) findViewById(R.id.Ostan);
        ImageView sImage = (ImageView) findViewById(R.id.sImage);
        sImage.setOnClickListener(this);
        if (cursor.moveToNext()) {
            desc.setTypeface(this.lotus);
            desc.setText(cursor.getString(1));
            TextView rightText = (TextView) findViewById(R.id.right_text);
            rightText.setTypeface(this.mitra);
            rightText.setText(cursor.getString(2));
            ostan.setTypeface(this.mitra);
            String string = cursor.getString(3);
            this.title = string;
            ostan.setText(string);
            try {
                AssetManager assets = getAssets();
                StringBuilder sb = new StringBuilder("Thumbnail/");
                String string2 = cursor.getString(4);
                this.img = string2;
                Bitmap bmp = BitmapFactory.decodeStream(assets.open(sb.append(string2).append(".jpg").toString()));
                sImage.setImageBitmap(bmp);
                StringTokenizer stoken = new StringTokenizer(cursor.getString(5), ";");
                StringBuffer ingredients = new StringBuffer("");
                while (stoken.hasMoreTokens()) {
                    ingredients.append(stoken.nextToken()).append("\n");
                }
                ingred.setTypeface(this.lotus);
                ingred.setText(ingredients.toString());
            } catch (IOException e) {
                throw new Error("Error decoding image" + e.getMessage());
            }
        }
        return cursor;
    }

    private void showEvents(Cursor cursor) {
    }

    @Override // android.view.View.OnClickListener
    public void onClick(View v) {
        startActivity(new Intent(this, (Class<?>) Touch.class).putExtra("IMG", this.img).putExtra("images1", this.images1));
    }

    @Override // android.app.Activity
    public boolean onCreateOptionsMenu(Menu menu) {
        super.onCreateOptionsMenu(menu);
        if (isFavorite(this.img)) {
            menu.add(0, 2, 1, getResources().getText(R.string.m_del_fav)).setIcon(android.R.drawable.ic_menu_delete);
        } else {
            menu.add(0, 1, 2, getResources().getText(R.string.m_add_fav)).setIcon(android.R.drawable.ic_menu_add);
        }
        menu.add(0, 5, 5, getResources().getText(R.string.m_main)).setIcon(R.drawable.m_home);
        return true;
    }

    @Override // android.app.Activity
    public boolean onPrepareOptionsMenu(Menu menu) {
        menu.clear();
        onCreateOptionsMenu(menu);
        return super.onPrepareOptionsMenu(menu);
    }

    @Override // android.app.Activity, android.view.Window.Callback
    public boolean onMenuItemSelected(int featureId, MenuItem item) {
        switch (item.getItemId()) {
            case 1:
                insert(this.img);
                break;
            case 2:
                if (isFavorite(this.img)) {
                    delete(this.img);
                    break;
                }
                break;
            case 5:
                startActivity(new Intent(this, (Class<?>) TabHostActivity.class).setFlags(67108864));
                break;
        }
        return super.onMenuItemSelected(featureId, item);
    }

    protected boolean isFavorite(String img) {
        Cursor c = null;
        boolean result = false;
        try {
            try {
                c = this.db.query(true, "FAV", null, "image = '" + img + "'", null, null, null, null, null);
                if (c.getCount() > 0) {
                    result = true;
                }
                if (c != null && !c.isClosed()) {
                    c.close();
                }
            } catch (SQLException e) {
                Log.e("Information", e.getMessage());
                if (c != null && !c.isClosed()) {
                    c.close();
                }
            }
            return result;
        } catch (Throwable th) {
            if (c != null && !c.isClosed()) {
                c.close();
            }
            throw th;
        }
    }

    protected void delete(String img) {
        this.db.delete("FAV", "image=" + img, null);
    }

    protected void insert(String img) {
        ContentValues values = new ContentValues();
        values.put(Constants.IMG, img);
        values.put(Constants.TITLE, this.title);
        this.db.insert("FAV", null, values);
    }

    @Override // android.app.Activity
    protected void onDestroy() {
        this.events.close();
        super.onDestroy();
    }
}

