                fitInViewZoom(true, true);
                break;
            case TabHostActivity.TAB_SEARCH_INDEX /* 2 */:
                if (this.mode == 1) {
                    this.matrix.set(this.savedMatrix);
                    this.matrix.postTranslate(rawEvent.getX() - this.start.x, rawEvent.getY() - this.start.y);
                    fitInView(true, true);
                    break;
                } else if (this.mode == 2) {
                    float newDist = spacing(rawEvent);
                    Log.d(TAG, "newDist=" + newDist);
                    if (newDist > 10.0f) {
                        float scale = newDist / this.oldDist;
                        if (scale > 1.0f) {
                            this.rect = new RectF(0.0f, 0.0f, this.bmp.getWidth(), this.bmp.getHeight());
                            this.matrix.mapRect(this.rect);
                            if (this.rect.height() <= this.bmp.getHeight() * 2 && this.rect.width() <= this.bmp.getWidth() * 2) {
                                this.matrix.set(this.savedMatrix);
                                this.matrix.postScale(scale, scale, this.mid.x, this.mid.y);
                                this.rect = new RectF(0.0f, 0.0f, this.bmp.getWidth(), this.bmp.getHeight());
                                this.matrix.mapRect(this.rect);
                                this.bmpW = (int) this.rect.width();
                                this.bmpH = (int) this.rect.height();
                                fitInView(true, true);
                                break;
                            }
                        } else {
                            this.rect = new RectF(0.0f, 0.0f, this.bmp.getWidth(), this.bmp.getHeight());
                            this.matrix.mapRect(this.rect);
                            if (this.rect.height() >= this.bmp.getHeight() && this.rect.width() >= this.bmp.getWidth()) {
                                this.matrix.set(this.savedMatrix);
                                this.matrix.postScale(scale, scale, this.mid.x, this.mid.y);
                                this.rect = new RectF(0.0f, 0.0f, this.bmp.getWidth(), this.bmp.getHeight());
                                this.matrix.mapRect(this.rect);
                                this.bmpW = (int) this.rect.width();
                                this.bmpH = (int) this.rect.height();
                                fitInView(true, true);
                                break;
                            }
                        }
                    }
                }
                break;
            case TabHostActivity.TAB_SERVICE_INDEX /* 5 */:
                this.oldDist = spacing(rawEvent);
                Log.d(TAG, "oldDist=" + this.oldDist);
                if (this.oldDist > 10.0f) {
                    this.savedMatrix.set(this.matrix);
                    midPoint(this.mid, rawEvent);
                    this.mode = 2;
                    Log.d(TAG, "mode=ZOOM");
                    break;
                }
                break;
        }
        this.view.setImageMatrix(this.matrix);
        return true;
    }

