    private float spacing(MotionEvent event) {
        float x = event.getX(0) - event.getX(1);
        float y = event.getY(0) - event.getY(1);
        return FloatMath.sqrt((x * x) + (y * y));
    }

    private void midPoint(PointF point, MotionEvent event) {
        float x = event.getX(0) + event.getX(1);
        float y = event.getY(0) + event.getY(1);
        point.set(x / 2.0f, y / 2.0f);
    }

    private final void fitInView(boolean horizontal, boolean vertical) {
        RectF rect = new RectF(0.0f, 0.0f, this.bmp.getWidth(), this.bmp.getHeight());
        this.matrix.mapRect(rect);
        float height = rect.height();
        float width = rect.width();
        float deltaX = 0.0f;
        float deltaY = 0.0f;
        if (vertical) {
            int viewHeight = this.view.getHeight();
            if (height < viewHeight) {
                deltaY = ((viewHeight - height) / 2.0f) - rect.top;
            } else if (rect.top > 0.0f) {
                deltaY = -rect.top;
            } else if (rect.bottom < viewHeight) {
                deltaY = this.view.getHeight() - rect.bottom;
            }
        }
        if (horizontal) {
            int viewWidth = this.view.getWidth();
            if (width < viewWidth) {
                deltaX = ((viewWidth - width) / 2.0f) - rect.left;
            } else if (rect.left > 0.0f) {
                deltaX = -rect.left;
            } else if (rect.right < viewWidth) {
                deltaX = viewWidth - rect.right;
            }
        }
        this.matrix.postTranslate(deltaX, deltaY);
    }

